<script lang="ts">
  import Panel from './Panel.svelte';
  import Meter from './Meter.svelte';
  import Transactions from './Transactions.svelte';
  import Icon from '$lib/components/Icon.svelte';
  import { apiPost } from '$lib/api/client';
  import { number as n, text, type Model, type Actions } from './model';
  let { m, a }: { m: Model; a: Actions } = $props();
  let search = $state(''); let category = $state(''); let account = $state(''); let txType = $state(''); let page = $state(1);
  const filtered = $derived(m.transactions.filter(row => (!search || text(row.name).toLowerCase().includes(search.toLowerCase())) && (!category || text(row.categoryId) === category) && (!account || text(row.accountId) === account) && (!txType || row.type === txType)));
  const balances = (row: Record<string, unknown>) => n(row.calculatedBalance ?? row.balance ?? row.initialBalance);
  const credit = $derived(m.accounts.filter(row => row.type === 'Crédito'));
  const creditLimit = $derived(credit.reduce((sum, row) => sum + n(row.creditLimit), 0));
  const creditUsed = $derived(credit.reduce((sum, row) => sum + Math.max(0, -balances(row)), 0));
  let from = $state(''); let to = $state(''); let transferAmount = $state<number | undefined>(); let destinationAmount = $state<number | undefined>(); let transferName = $state(''); let transferError = $state(''); let saving = $state(false);
  const crossCurrency = $derived(from && to && m.accounts.find(c => c.id === n(from))?.currency !== m.accounts.find(c => c.id === n(to))?.currency);
  async function transfer(event: SubmitEvent) {
    event.preventDefault(); saving = true; transferError = '';
    try { await apiPost('/transfers', { name: transferName || m.l('Account transfer','Transferencia entre cuentas'), amount: transferAmount, sourceAccountId: n(from), destinationAccountId: n(to), date: new Date().toISOString(), ...(crossCurrency ? { destinationAmount } : {}) }); transferAmount = undefined; transferName = ''; await a.refresh(); a.notify(m.l('Transfer saved.','Transferencia guardada.')); }
    catch (e) { transferError = e instanceof Error ? e.message : String(e); } finally { saving = false; }
  }
</script>

{#if m.route === 'cuentas'}
  <Panel title={m.l('My accounts','Mis cuentas')}>
    {#snippet action()}<button class="cp-button small" onclick={() => a.edit('accounts')}>+ {m.l('Add account','Agregar cuenta')}</button>{/snippet}
    <div class="cp-account-grid">{#each m.accounts.filter(row => row.type !== 'Crédito') as row}<article class="cp-account cp-tile"><span class="cp-account-brand"><Icon name={row.type === 'Efectivo' ? 'wallet' : 'building'} size={20}/><b>{text(row.bank) || text(row.name)}</b></span><span>{text(row.name)}</span><strong class="cp-number cp-yellow">{m.money(balances(row), text(row.currency) || m.currency)}</strong><small>{text(row.currency)}</small><div class="cp-card-footer"><button class="cp-link" onclick={()=>a.edit('account-detail',row)}>{m.l('Details','Detalles')}</button><button class="cp-link" onclick={()=>a.edit('accounts',row)}>{m.l('Edit','Editar')}</button><button class="cp-link cp-red" onclick={()=>a.edit('account-deactivate',row)}>{m.l('Deactivate','Desactivar')}</button></div></article>{:else}<p class="cp-empty">{m.l('Add an account to get started.','Agrega una cuenta para comenzar.')}</p>{/each}</div>
  </Panel>
  <Panel title={m.l('Credit cards','Tarjetas de crédito')}><div class="cp-account-grid">{#each credit as row}<article class="cp-tile cp-credit"><div class="cp-card-heading"><Icon name="credit-card" size={22}/><strong>{text(row.name)}</strong><button class="cp-icon-button" aria-label={m.l('Edit credit card','Editar tarjeta')} onclick={() => a.edit('accounts', row)}>···</button></div><div class="cp-key-values"><span>{m.l('Credit limit','Límite')}</span><b>{m.money(row.creditLimit)}</b><span>{m.l('Used','Utilizado')}</span><b class="cp-red">{m.money(Math.max(0, -balances(row)))}</b></div><Meter value={Math.max(0, -balances(row))} max={n(row.creditLimit)} tone={-balances(row) / n(row.creditLimit) > .7 ? 'red' : 'cyan'} label={m.l('Credit utilization','Utilización de crédito')}/><div class="cp-card-footer">{m.l('Available','Disponible')}<strong>{m.money(n(row.creditLimit) - Math.max(0, -balances(row)))}</strong></div><button class="cp-button ghost small" onclick={()=>a.edit('account-detail',row)}>{m.l('Statement & history','Estado e historial')}</button></article>{:else}<p class="cp-empty">{m.l('No credit cards yet.','Aún no hay tarjetas de crédito.')}</p>{/each}</div></Panel>
  <Panel title={m.l('Credit utilization summary','Resumen de utilización')}><div class="cp-stats plain"><div class="cp-stat"><span>{m.l('Total credit','Crédito total')}</span><strong>{m.money(creditLimit)}</strong></div><div class="cp-stat"><span>{m.l('Credit used','Crédito utilizado')}</span><strong class="cp-red">{m.money(creditUsed)}</strong><Meter value={creditUsed} max={creditLimit} tone="red" label={m.l('Used credit','Crédito utilizado')}/></div><div class="cp-stat"><span>{m.l('Available credit','Crédito disponible')}</span><strong>{m.money(creditLimit - creditUsed)}</strong></div></div></Panel>
{:else if m.route === 'transacciones'}
  <div class="cp-toolbar"><input aria-label={m.l('Filter visible transactions','Filtrar movimientos visibles')} placeholder={m.l('Filter visible transactions…','Filtrar movimientos visibles…')} bind:value={search} oninput={() => page = 1}/><select aria-label={m.l('Account','Cuenta')} bind:value={account} onchange={() => page = 1}><option value="">{m.l('All accounts','Todas las cuentas')}</option>{#each m.accounts as row}<option value={text(row.id)}>{text(row.name)}</option>{/each}</select><select aria-label={m.l('Category','Categoría')} bind:value={category} onchange={() => page = 1}><option value="">{m.l('All categories','Todas las categorías')}</option>{#each m.categories as row}<option value={text(row.id)}>{text(row.name)}</option>{/each}</select><button class="cp-button" onclick={() => a.edit('transactions')}>+ {m.l('New transaction','Nuevo movimiento')}</button></div>
  <div class="cp-tabs">{#each [['',m.l('All','Todos')],['Ingreso',m.l('Income','Ingresos')],['Gasto',m.l('Expenses','Gastos')]] as [value,label]}<button class:active={txType === value} onclick={() => { txType=value; page=1; }}>{label}</button>{/each}</div>
  <Panel title={m.l('Transaction log','Registro de movimientos')}><Transactions {m} {a} items={filtered.slice((page - 1) * 20, page * 20)}/><footer class="cp-pagination"><span>{Math.min((page - 1) * 20 + 1, filtered.length)}–{Math.min(page * 20, filtered.length)} / {filtered.length}{m.transactionTotal > 100 ? ` (${m.transactionTotal} ${m.l('total','en total')})` : ''}</span><div><button class="cp-button ghost small" disabled={page <= 1} onclick={() => page--}>‹</button><span>{page}</span><button class="cp-button ghost small" disabled={page * 20 >= filtered.length} onclick={() => page++}>›</button></div>{#if m.transactionTotal > 100}{/if}</footer></Panel>
{:else}
  <div class="cp-split">
    <Panel title={m.l('New transfer','Nueva transferencia')}><form class="cp-form" onsubmit={transfer}><label>{m.l('From','Desde')}<select bind:value={from} required><option value="">{m.l('Select account','Selecciona cuenta')}</option>{#each m.accounts as row}<option value={text(row.id)}>{text(row.name)} · {m.money(balances(row),text(row.currency) || m.currency)}</option>{/each}</select></label><label>{m.l('To','Hacia')}<select bind:value={to} required><option value="">{m.l('Select account','Selecciona cuenta')}</option>{#each m.accounts.filter(row => row.id !== n(from)) as row}<option value={text(row.id)}>{text(row.name)}</option>{/each}</select></label><label>{m.l('Amount','Monto')}<input required type="number" min="0.01" step="0.01" bind:value={transferAmount}/></label>{#if crossCurrency}<label>{m.l('Destination amount','Monto destino')}<input required type="number" min="0.01" step="0.01" bind:value={destinationAmount}/></label>{/if}<label>{m.l('Description (optional)','Descripción (opcional)')}<input bind:value={transferName}/></label>{#if transferError}<p class="cp-error" role="alert">{transferError}</p>{/if}<button class="cp-button" disabled={saving}>{saving ? '…' : m.l('Save transfer','Guardar transferencia')} →</button></form></Panel>
    <Panel title={m.l('Quick transfers','Transferencias rápidas')}><div class="cp-quick-transfers">{#each m.accounts.slice(0,4) as row}<div><Icon name="wallet" size={24}/><span><b>{text(row.name)}</b><small>{text(row.bank) || text(row.currency)}</small></span><button class="cp-button small" onclick={() => a.edit('transfers', { id:0, destinationAccountId:row.id, name:m.l('Transfer to ','Transferencia a ') + text(row.name) })}>{m.l('Transfer','Transferir')}</button></div>{/each}</div></Panel>
  </div>
  <Panel title={m.l('Transfer history','Historial de transferencias')}><div class="cp-table-wrap"><table class="cp-table"><thead><tr><th>{m.l('Date','Fecha')}</th><th>{m.l('Description','Descripción')}</th><th>{m.l('From','Origen')}</th><th>{m.l('To','Destino')}</th><th class="cp-right">{m.l('Amount','Monto')}</th><th></th></tr></thead><tbody>{#each m.transfers as row}<tr><td>{m.date(row.date)}</td><td>{text(row.name)}</td><td>{m.account(row.sourceAccountId)}</td><td>{m.account(row.destinationAccountId)}</td><td class="cp-number cp-right">{m.money(row.amount)}</td><td><button class="cp-icon-button" aria-label={m.l('Edit transfer','Editar transferencia')} onclick={() => a.edit('transfers',row)}>···</button><button class="cp-link cp-red" onclick={()=>a.edit('transfer-delete',row)}>{m.l('Delete','Eliminar')}</button></td></tr>{:else}<tr><td colspan="6" class="cp-empty">{m.l('No transfers yet.','Aún no hay transferencias.')}</td></tr>{/each}</tbody></table></div></Panel>
{/if}
